/* lessons.js: the rules drawer teaches by doing. Each game has 3-4 steps: a goal, an example the visitor plays, the consequence
   highlighted on the example, and one complication beginners miss. A step never advances by itself; "Show me" plays it out.
   window.ZLessons.get(slug) -> [{title, text, mount(host, api)}]   api: note(html), ok(), reset()   mount may return {show(): Promise} */
(function(){
const $=(t,c,h)=>{ const e=document.createElement(t); if(c) e.className=c; if(h!==undefined) e.innerHTML=h; return e; };
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const X='<svg viewBox="0 0 20 20" class="ls-mk"><path d="M4.5 4.5L15.5 15.5M15.5 4.5L4.5 15.5"/></svg>', O='<svg viewBox="0 0 20 20" class="ls-mk"><circle cx="10" cy="10" r="6"/></svg>';
const CSS=`
.ls-stage{display:flex;flex-direction:column;align-items:center;gap:12px;padding:16px 8px;margin:10px 0;background:var(--surf2);border-radius:18px;min-height:120px;--ls-cell:calc(58px * var(--ls-k,1))}
.ls-note{font:500 15px/1.5 var(--font-sans);color:var(--fg);min-height:3em;text-align:center;max-width:46ch}.ls-note b{color:var(--fg)}
.ls-note.ok{font-weight:600}
.ls-note.ok::before{content:"";display:inline-block;width:16px;height:16px;margin-right:6px;vertical-align:-2px;background:currentColor;-webkit-mask:url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22><path fill=%22none%22 stroke=%22black%22 stroke-width=%223%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22 d=%22M5 13l4 4L19 7%22/></svg>') center/contain no-repeat;mask:url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22><path fill=%22none%22 stroke=%22black%22 stroke-width=%223%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22 d=%22M5 13l4 4L19 7%22/></svg>') center/contain no-repeat}
.ls-grid{display:grid;gap:5px;padding:5px;background:var(--g4);border-radius:13px}
.ls-c{position:relative;width:clamp(40px,15vw,var(--ls-cell));aspect-ratio:1;border:none;border-radius:9px;background:var(--surf);color:var(--fg);display:flex;align-items:center;justify-content:center;cursor:pointer;padding:0;transition:background .12s}
.ls-c:hover:not(:disabled){background:var(--surf3)}.ls-c:disabled{cursor:default;opacity:1}
.ls-mk{width:64%;height:64%;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round}
.ls-c.tgt{outline:2.5px dashed var(--fg);outline-offset:-5px}
.ls-c.win{background:var(--fg);color:var(--bg)}
.ls-c.dim{opacity:.4}
.ls-c.last::after{content:"";position:absolute;top:5px;right:5px;width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.7}
.ls-pop{animation:lspop .32s cubic-bezier(.3,1.5,.5,1)}@keyframes lspop{from{transform:scale(.6);opacity:.2}}
.ls-no{animation:lsno .38s}@keyframes lsno{20%{transform:translateX(-5px)}50%{transform:translateX(5px)}80%{transform:translateX(-3px)}}
.ls-ult{position:relative;display:grid;grid-template-columns:repeat(3,auto);gap:7px}
.ls-sub{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding:3px;border-radius:10px;background:var(--g4);position:relative}
.ls-sub.dest{box-shadow:0 0 0 3px var(--fg)}.ls-sub.free{box-shadow:0 0 0 2px var(--fg)}.ls-sub.closed .ls-c{opacity:.35}
.ls-sub .ls-c{width:clamp(22px,7.4vw,calc(var(--ls-cell)*.56));border-radius:5px}
.ls-sub .own{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:var(--bg);border-radius:10px;color:var(--fg);pointer-events:none}.ls-sub .own .ls-mk{width:70%;height:70%;stroke-width:3}
.ls-line{position:absolute;pointer-events:none;overflow:visible;inset:0;width:100%;height:100%}.ls-line line{stroke:var(--fg);stroke-width:2;stroke-dasharray:5 5;animation:lsdash .6s linear infinite}
@keyframes lsdash{to{stroke-dashoffset:-20}}
.ls-layers{display:flex;gap:12px;flex-wrap:wrap;justify-content:center}
.ls-layer{display:flex;flex-direction:column;align-items:center;gap:6px;font:600 11.5px var(--font-mono);letter-spacing:.04em;color:var(--g5)}
.ls-c.ls-c3{width:clamp(30px,8.6vw,calc(var(--ls-cell)*.78))}
.ls-chips{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;max-width:420px}
.ls-chip{min-height:42px;padding:0 15px;border:1.5px solid transparent;border-radius:11px;background:var(--surf3);color:var(--fg);font:600 14.5px var(--font-sans);cursor:pointer}
.ls-chip[aria-pressed=true]{background:var(--fg);color:var(--bg)}
.ls-chip[aria-pressed=true]::before{content:"\\2713\\00a0"}
.ls-chip.ok{border-color:var(--fg);border-style:dashed}
.ls-btn{min-height:44px;padding:0 18px;border:none;border-radius:11px;background:var(--fg);color:var(--bg);font:600 14.5px var(--font-sans);cursor:pointer}.ls-btn.ghost{background:var(--surf3);color:var(--fg)}
.ls-btn:focus-visible,.ls-chip:focus-visible,.ls-c:focus-visible,.ls-tok:focus-visible{outline:2px solid var(--fg);outline-offset:2px}
.ls-pieces{display:flex;gap:10px;align-items:flex-end;justify-content:center;flex-wrap:wrap}.ls-pieces svg{width:calc(56px * var(--ls-k,1));height:calc(74px * var(--ls-k,1));background:var(--surf);border-radius:10px;padding:4px;color:var(--fg)}.ls-pieces svg.win{outline:3px solid var(--fg)}
.ls-qb{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;padding:5px;background:var(--g4);border-radius:14px;width:min(100%,calc(var(--ls-cell)*4.6))}
.ls-qc{aspect-ratio:1;border-radius:9px;background:var(--surf);display:flex;align-items:center;justify-content:center;padding:6%;color:var(--fg)}
.ls-qc svg{width:auto;height:100%}.ls-qc.win{box-shadow:inset 0 0 0 3px var(--fg)}.ls-qc.last{box-shadow:inset 0 0 0 2px var(--g6)}
.ls-qrow{display:flex;align-items:center;gap:12px}.ls-qhand{width:calc(60px * var(--ls-k,1));height:calc(78px * var(--ls-k,1));border:2px dashed var(--g4);border-radius:12px;display:flex;align-items:center;justify-content:center;padding:4px;color:var(--fg)}.ls-qhand svg{height:100%;width:auto}
.ls-qlab{font:600 11.5px var(--font-mono);letter-spacing:.06em;text-transform:uppercase;color:var(--g5)}
.ls-nim{display:flex;gap:22px;align-items:flex-end}.ls-pile{display:flex;flex-direction:column-reverse;gap:5px;align-items:center;border-radius:10px}.ls-pile b{font:700 16px var(--font-sans);margin-top:6px}
.ls-tok{width:calc(clamp(48px,14vw,64px) * var(--ls-k,1));height:calc(24px * var(--ls-k,1));border:none;border-radius:6px;background:var(--fg);cursor:pointer;padding:0}.ls-tok.pv{background:transparent;outline:2px dashed var(--fg);outline-offset:-2px}.ls-tok:disabled{cursor:default}
.ls-choc{background:var(--fg);color:var(--bg)}.ls-choc:hover:not(:disabled){background:var(--g6)}.ls-choc.pv{background:repeating-linear-gradient(135deg,var(--g5) 0 5px,var(--fg) 5px 10px)}
.ls-choc.gone{background:transparent;outline:2px dashed var(--g4);outline-offset:-4px;color:transparent}
.ls-svg{width:min(100%,var(--ls-w,340px));height:auto;color:var(--fg)}
.ls-real{width:100%;display:flex;flex-direction:column;align-items:center;max-width:var(--ls-w,440px)}
.ls-real .tt-board,.ls-real .dm svg,.ls-real .pg svg{max-width:100%}
.ls-real .pg{min-width:0}
.ls-turn{display:inline-flex;align-items:center;gap:9px;font:700 14px var(--font-sans);color:var(--fg);background:var(--surf3);border-radius:999px;padding:7px 14px 7px 10px}
.ls-dir{display:inline-block;border:2.5px solid currentColor;border-radius:4px}.ls-dir.v{width:10px;height:20px}.ls-dir.h{width:20px;height:10px}
.ls-room{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;max-width:400px}.ls-day{border-radius:12px;padding:10px 12px;background:var(--surf);font:500 13.5px/1.4 var(--font-sans);color:var(--g6)}.ls-day.past{opacity:.6}.ls-day b{display:block;font:700 22px var(--font-sans);color:var(--fg)}.ls-day i{font:600 10.5px var(--font-mono);letter-spacing:.08em;text-transform:uppercase;font-style:normal;color:var(--g5)}
.ls-rulechip{font:600 13px var(--font-sans);color:var(--g6);background:var(--bg);border:1px solid var(--g3);border-radius:999px;padding:5px 12px}.ls-rulechip b{color:var(--fg)}.ls-outcome{font:500 14.5px/1.45 var(--font-sans);color:var(--fg);text-align:center;max-width:300px;animation:lsin .35s both}.ls-outcome b{display:block;font:700 20px var(--font-sans);margin-bottom:2px}
.ls-lines{font:600 15px/1.6 var(--font-sans);color:var(--fg);text-align:center}.ls-lines div{animation:lsin .35s both}@keyframes lsin{from{opacity:0;transform:translateY(4px)}to{opacity:1}}
@media (min-width:701px){#gdrawer .ls-stage{--ls-cell:calc(74px * var(--ls-k,1))}}
@media (prefers-reduced-motion:reduce){.ls-pop,.ls-no{animation:none}}
`;
const st=$('style'); st.id='ls-css'; st.textContent=CSS; document.head.appendChild(st);
const cellBtn=(html,cls,fn)=>{ const b=$('button','ls-c'+(cls?' '+cls:''),html||''); b.type='button'; if(fn) b.onclick=fn; return b; };
const grid=(n,fn)=>{ const g=$('div','ls-grid'); g.style.gridTemplateColumns=`repeat(${n},auto)`; return g; };
const LINES4=(()=>{ const L=[]; for(let i=0;i<4;i++){ L.push([0,1,2,3].map(k=>i*4+k)); L.push([0,1,2,3].map(k=>k*4+i)); } L.push([0,5,10,15],[3,6,9,12]); return L; })();

/* Every strategy lesson follows the same shape, core rules first:
   goal (what are you trying to achieve) > watch (one legal move, played out) > try (the same move on a practice board)
   > cant (a restriction, with an attempted illegal move explained) > end (how the game finishes). Practice boards are
   their own small states and never touch a live match. "Skip practice" jumps past the try/cant steps. */
const sh=(el,cls,ms)=>{ el.classList.add(cls); setTimeout(()=>el.classList.remove(cls),ms||420); };
const deny=(el,a,msg)=>{ if(el) sh(el,'ls-no'); a.note(msg); if(window.ZS) ZS.play('tap'); };

/* ---- 4x4 ---- */
function ttt4(){ const board=(h,set,cls,click)=>{ const g=grid(4), cells=[]; for(let i=0;i<16;i++){ const c=cellBtn(set[i]===1?X:set[i]===2?O:'',(cls&&cls[i])||'',()=>click&&click(i,c)); cells.push(c); g.appendChild(c); } h.appendChild(g); return cells; };
 return [
 {kind:'goal',title:'Make four in a row',text:'Take turns placing X and O on a 4×4 board. <b>Four of your marks in a row, a column or a main diagonal</b> wins.',mount(h,a){ const set={0:1,5:1,10:1,15:1,3:2,7:2,8:2}; const cells=board(h,set); cells.forEach(c=>c.disabled=true); [0,5,10,15].forEach(k=>cells[k].classList.add('win')); a.note('X has four on the diagonal, so X wins.'); }},
 {kind:'watch',title:'Place one mark',text:'On your turn, put <b>one mark in any empty square</b>. Then your opponent does the same.',mount(h,a){ let cells; const build=()=>{ h.innerHTML=''; cells=board(h,{0:1,10:2}); cells.forEach(c=>c.disabled=true); a.note('X to move.'); }; build();
   return {reset:build, async show(){ await sleep(300); cells[5].innerHTML=X; sh(cells[5],'ls-pop'); cells[5].classList.add('last'); a.note('<b>X takes an empty square.</b> One mark, one square, and the turn passes.'); await sleep(1100); cells[5].classList.remove('last'); cells[6].innerHTML=O; sh(cells[6],'ls-pop'); cells[6].classList.add('last'); a.note('<b>Now O places one mark.</b> Players keep alternating like this.'); }}; }},
 {kind:'try',title:'Place the fourth X',text:'X has three on the diagonal. <b>Place the fourth.</b>',mount(h,a){ const set={0:1,5:1,10:1,3:2,7:2,8:2}; let done=false; const cells=board(h,set,{15:'tgt'},(i,c)=>{ if(done) return; if(set[i]){ deny(c,a,'That square is taken. A mark can only go in an <b>empty</b> square.'); return; } if(i!==15){ a.note('A fine square, but it does not make four. Look for the dashed one.'); return; } done=true; c.innerHTML=X; c.classList.remove('tgt'); [0,5,10,15].forEach(k=>cells[k].classList.add('win')); a.note('<b>Four in a row on the diagonal.</b> The game ends the moment a line of four is complete.'); a.ok(); }); a.note('Choose a square.'); return {async show(){ cells[15].click(); }}; }},
 {kind:'cant',title:'Rows don’t wrap around',text:'The end of one row <b>does not connect</b> to the start of the next. Try to “finish” this line.',mount(h,a){ const set={2:1,3:1,4:1,9:2,10:2,14:2}; let done=false; const cells=board(h,set,{5:'tgt'},(i,c)=>{ if(done) return; if(set[i]){ deny(c,a,'That square is taken.'); return; } if(i!==5){ a.note('Try the dashed square: it continues the marks in reading order.'); return; } done=true; c.innerHTML=X; [2,3,4,5].forEach(k=>cells[k].classList.add('dim')); a.note('<b>Not a line.</b> Squares 3 and 4 sit on different rows, so these four only look connected in reading order. Nothing is completed.'); a.ok(); }); a.note('X has three marks in reading order. Try the dashed square.'); return {async show(){ cells[5].click(); }}; }},
 {kind:'end',title:'Win, or fill the board',text:'The first line of four wins. If all sixteen squares fill with no line of four, <b>the game is a draw</b>.',mount(h,a){ const full=[1,2,1,2, 1,2,2,1, 2,1,1,2, 2,1,2,1]; const set={}; full.forEach((v,i)=>set[i]=v); const cells=board(h,set); cells.forEach(c=>c.disabled=true); a.note('A full board with no four in a row: a draw. With perfect play, 4×4 is always a draw.'); }} ]; }

/* ---- recursive ---- */
const NAMES9=['top-left','top','top-right','left','centre','right','bottom-left','bottom','bottom-right'];
function ult(){ const boards=(h,cfg)=>{ const wrap=$('div','ls-ult'); const subs=[],cells=[]; for(let b=0;b<9;b++){ const s=$('div','ls-sub'); subs.push(s); cells.push([]); for(let c=0;c<9;c++){ const cb=cellBtn('','',()=>cfg.click(b,c,cb)); cells[b].push(cb); s.appendChild(cb); } wrap.appendChild(s); } const svgNS='http://www.w3.org/2000/svg'; const line=document.createElementNS(svgNS,'svg'); line.setAttribute('class','ls-line'); wrap.appendChild(line); h.appendChild(wrap); return {wrap,subs,cells,line,connect(from,to){ const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),w=wrap.getBoundingClientRect(); line.innerHTML=`<line x1="${a.left+a.width/2-w.left}" y1="${a.top+a.height/2-w.top}" x2="${b.left+b.width/2-w.left}" y2="${b.top+b.height/2-w.top}"/>`; }}; };
 /* "Try it" accepts any cell the visitor actually clicks, and the next step follows that exact choice. */
 let lastC=2;
 return [
 {kind:'goal',title:'Win three boards in a row',text:'Nine small boards make one big one. Win a small board with three in a row inside it. <b>Win three small boards in a line</b> to win the game.',mount(h,a){ const B=boards(h,{click(){}}); B.cells.forEach(r=>r.forEach(c=>c.disabled=true)); [0,4,8].forEach(b=>{ B.subs[b].insertAdjacentHTML('beforeend',`<div class="own">${X}</div>`); }); a.note('X has won the top-left, centre and bottom-right boards: a diagonal of boards.'); }},
 {kind:'watch',title:'Your cell picks their board',text:'Play anywhere you are allowed. <b>The cell you choose inside a small board sends your opponent to the board in that same position.</b>',mount(h,a){ let B; const build=()=>{ h.innerHTML=''; B=boards(h,{click(){}}); B.cells.forEach(r=>r.forEach(c=>c.disabled=true)); a.note('X plays in the centre board.'); }; build();
   return {reset:build, async show(){ await sleep(300); const c=B.cells[4][2]; c.innerHTML=X; c.classList.add('last'); sh(c,'ls-pop'); await sleep(600); B.subs[2].classList.add('dest'); B.connect(c,B.subs[2]); a.note('<b>X played the top-right cell, so O must play in the top-right board.</b>'); await sleep(1300); const o=B.cells[2][6]; o.innerHTML=O; o.classList.add('last'); sh(o,'ls-pop'); c.classList.remove('last'); B.subs[2].classList.remove('dest'); B.subs[6].classList.add('dest'); B.connect(o,B.subs[6]); a.note('<b>O answers in the top-right board, using its bottom-left cell</b>, so X now goes to the bottom-left board.'); }}; }},
 {kind:'try',title:'Send your opponent somewhere',text:'Play X in <b>any cell of the centre board</b>. Watch which board it points to.',mount(h,a){ const B=boards(h,{click(b,c,el){ if(B.placed) return; if(b!==4){ deny(el,a,'Use the centre board for this practice.'); return; } B.placed=true; lastC=c; B.cells[b][c].innerHTML=X; B.cells[b][c].classList.add('last'); B.subs[c].classList.add('dest'); B.connect(B.cells[b][c],B.subs[c]); a.note(`<b>You played the ${NAMES9[c]} cell, so your opponent must play in the ${NAMES9[c]} board.</b>`); a.ok(); }}); B.subs.forEach((s,i)=>{ if(i!==4) B.cells[i].forEach(c=>c.classList.add('dim')); }); a.note('Choose any cell in the centre board.'); return {async show(){ B.cells[4][2].click(); }}; }},
 {kind:'cant',title:'Play where you were sent',text:'You must play <b>inside the highlighted board</b>. Try a cell somewhere else first.',mount(h,a){ const dst=lastC; const B=boards(h,{click(b,c,el){ if(B.done) return; if(b!==dst){ deny(el,a,`<b>Not allowed.</b> The last move sent you to the ${NAMES9[dst]} board, so every other board is off limits this turn.`); return; } B.done=true; B.cells[b][c].innerHTML=O; B.cells[b][c].classList.add('last'); B.subs[dst].classList.remove('dest'); B.subs[c].classList.add('dest'); B.connect(B.cells[b][c],B.subs[c]); a.note(`<b>Allowed.</b> You played inside the ${NAMES9[dst]} board, and your cell now sends X to the ${NAMES9[c]} board.`); a.ok(); }}); B.cells[4][dst].innerHTML=X; B.cells[4][dst].classList.add('last'); B.subs[dst].classList.add('dest'); B.cells.forEach((r,i)=>r.forEach(c=>{ if(i!==dst) c.classList.add('dim'); })); a.note(`You are O, sent to the ${NAMES9[dst]} board. Try another board, then the highlighted one.`); return {async show(){ const free=[...B.cells[dst].keys()].find(i=>!B.cells[dst][i].innerHTML); B.cells[dst][free].click(); }}; }},
 {kind:'rule',practice:true,title:'Sent to a closed board? Play anywhere',text:'If your cell points to a board that is <b>already won or full</b>, your opponent may play in <b>any</b> open board.',mount(h,a){ const closed=lastC===4?2:lastC; const B=boards(h,{click(b,c,el){ if(B.done) return; if(b===closed){ deny(el,a,'That board is closed. No more moves go there.'); return; } B.done=true; B.cells[b][c].innerHTML=X; B.cells[b][c].classList.add('last'); if(c===closed){ B.subs.forEach((s,i)=>{ if(i!==closed) s.classList.add('free'); }); B.connect(B.cells[b][c],B.subs[closed]); a.note(`<b>You pointed at the ${NAMES9[closed]} board, but it is already won.</b> O may now choose any open board.`); a.ok(); } else { B.subs[c].classList.add('dest'); a.note(`That points to an open board. Try a ${NAMES9[closed]} cell to see what a closed board does.`); B.done=false; setTimeout(()=>{ B.cells[b][c].innerHTML=''; B.cells[b][c].classList.remove('last'); B.subs[c].classList.remove('dest'); },900); } }}); B.subs[closed].classList.add('closed'); B.subs[closed].insertAdjacentHTML('beforeend',`<div class="own">${O}</div>`); a.note(`The ${NAMES9[closed]} board belongs to O. Play the ${NAMES9[closed]} cell of any open board.`); return {async show(){ B.cells[4][closed].click(); }}; }},
 {kind:'end',title:'How it ends',text:'Three small boards in a line wins. A full board nobody won is neutral. If every board closes with no line of boards, <b>it is a draw</b>.',mount(h,a){ const B=boards(h,{click(){}}); B.cells.forEach(r=>r.forEach(c=>c.disabled=true)); [2,4,6].forEach(b=>{ B.subs[b].insertAdjacentHTML('beforeend',`<div class="own">${O}</div>`); }); [0,8].forEach(b=>{ B.subs[b].insertAdjacentHTML('beforeend',`<div class="own">${X}</div>`); }); a.note('O owns three boards on the other diagonal, so O wins the game.'); }} ]; }

/* ---- 3D ---- */
function cube(){ const layers=(h,set,cb)=>{ const wrap=$('div','ls-layers'); const cells=[]; for(let z=0;z<3;z++){ const col=$('div','ls-layer'); const g=grid(3); cells.push([]); for(let i=0;i<9;i++){ const k=z*9+i; const c=cellBtn(set[k]===1?X:set[k]===2?O:'','',()=>cb&&cb(k,c)); if(set[k]) c.dataset.taken='1'; c.classList.add('ls-c3'); cells[z].push(c); g.appendChild(c); } col.appendChild(g); col.append(`layer ${z+1}${z===0?' · top':z===2?' · bottom':''}`); wrap.appendChild(col); } h.appendChild(wrap); return cells; };
 return [
 {kind:'goal',title:'Three in a straight line',text:'A 3×3×3 cube has 27 positions, shown here as three layers. <b>Three of your marks in a straight line wins</b>: inside a layer, or straight through the layers.',mount(h,a){ const cells=layers(h,{4:1,13:1,22:1,0:2,10:2}); cells.flat().forEach(c=>c.disabled=true); [cells[0][4],cells[1][4],cells[2][4]].forEach(c=>c.classList.add('win')); a.note('The same square in each layer lines up through the cube. X has a line.'); }},
 {kind:'watch',title:'Place one mark anywhere',text:'There is no gravity: <b>any empty position</b> is available, in any layer.',mount(h,a){ let cells; const build=()=>{ h.innerHTML=''; cells=layers(h,{}); cells.flat().forEach(c=>c.disabled=true); a.note('X to move.'); }; build();
   return {reset:build, async show(){ await sleep(300); cells[1][4].innerHTML=X; cells[1][4].classList.add('last'); sh(cells[1][4],'ls-pop'); a.note('<b>X takes the very centre of the cube</b> (layer 2, middle). It sits on more lines than any other position.'); await sleep(1300); cells[1][4].classList.remove('last'); cells[0][0].innerHTML=O; cells[0][0].classList.add('last'); sh(cells[0][0],'ls-pop'); a.note('<b>O answers with a corner of layer 1.</b> Turns alternate.'); }}; }},
 {kind:'try',title:'Finish the line through the layers',text:'X holds the centre of layers 1 and 2. <b>Take the centre of layer 3.</b>',mount(h,a){ let done=false; const set={4:1,13:1,0:2,10:2}; const cells=layers(h,set,(k,c)=>{ if(done) return; if(set[k]){ deny(c,a,'That position is taken.'); return; } if(k!==22){ a.note('Legal, but not a line. Look for the same square in the third layer.'); return; } done=true; c.innerHTML=X; [cells[0][4],cells[1][4],cells[2][4]].forEach(x=>x.classList.add('win')); a.note('<b>A straight line through the layers.</b> Same square, three layers: three in a row.'); a.ok(); }); cells[2][4].classList.add('tgt'); a.note('Choose a position.'); return {async show(){ cells[2][4].click(); }}; }},
 {kind:'cant',title:'Bent lines don’t count',text:'All three marks must sit on <b>one straight line</b>. This shape bends. Complete it and see.',mount(h,a){ let done=false; const set={0:1,13:1,3:2,7:2}; const cells=layers(h,set,(k,c)=>{ if(done) return; if(set[k]){ deny(c,a,'That position is taken.'); return; } if(k!==20){ a.note('Try the dashed position to see why the shape does not win.'); return; } done=true; c.innerHTML=X; [cells[0][0],cells[1][4],cells[2][2]].forEach(x=>x.classList.add('dim')); a.note('<b>No win.</b> Layer 1 top-left, layer 2 centre, layer 3 top-right turns a corner. A straight line would continue to layer 3 <b>bottom-right</b>.'); a.ok(); }); cells[2][2].classList.add('tgt'); a.note('Place X on the dashed position.'); return {async show(){ cells[2][2].click(); }}; }},
 {kind:'end',title:'Corner to corner wins too',text:'Lines also run <b>diagonally through the cube</b>: 49 lines in all. The first line wins. A full cube always contains a line, so there are no draws.',mount(h,a){ let done=false; const set={0:1,13:1,3:2,7:2}; const cells=layers(h,set,(k,c)=>{ if(done) return; if(set[k]){ deny(c,a,'That position is taken.'); return; } if(k!==26){ a.note('Not that one. Follow the diagonal from layer 1 top-left.'); return; } done=true; c.innerHTML=X; [cells[0][0],cells[1][4],cells[2][8]].forEach(x=>x.classList.add('win')); a.note('<b>X wins corner to corner.</b> Layer 1 top-left, layer 2 centre, layer 3 bottom-right.'); a.ok(); }); cells[2][8].classList.add('tgt'); a.note('Finish the diagonal.'); return {async show(){ cells[2][8].click(); }}; }} ]; }

/* ---- nim ---- */
function nim(){ const pile=(h,start,opts)=>{ const state=start.slice(); const box=$('div','ls-nim'); const render=()=>{ box.innerHTML=''; state.forEach((n,i)=>{ const p=$('div','ls-pile'); for(let j=0;j<n;j++){ const t=$('button','ls-tok'); t.type='button'; t.setAttribute('aria-label',`pile ${i+1}: take ${n-j}`); t.onmouseenter=()=>[...p.querySelectorAll('.ls-tok')].forEach((x,k)=>{ if(k>=j) x.classList.add('pv'); }); t.onmouseleave=()=>p.querySelectorAll('.ls-tok').forEach(x=>x.classList.remove('pv')); t.onclick=()=>opts.take(i,n-j,state,render,t); p.appendChild(t); } p.appendChild($('b','',n?String(n):'0')); box.appendChild(p); }); }; render(); h.appendChild(box); return {state,render,box}; };
 const leave=async(P,i,n)=>{ const toks=[...P.box.querySelectorAll('.ls-pile')[i].querySelectorAll('.ls-tok')]; toks.slice(toks.length-n).forEach(t=>t.classList.add('pv')); await sleep(700); P.state[i]-=n; P.render(); };
 return [
 {kind:'goal',title:'Take the last token',text:'Piles of tokens, two players. In the normal game, <b>whoever takes the last token wins</b>.',mount(h,a){ const P=pile(h,[3,5,2],{take(){ a.note('This is only a picture. The next steps let you play.'); }}); P.box.querySelectorAll('.ls-tok').forEach(t=>t.disabled=true); a.note('Three piles: 3, 5 and 2 tokens.'); }},
 {kind:'watch',title:'Take from one pile',text:'On your turn, take <b>one or more tokens from a single pile</b>. You may take the whole pile.',mount(h,a){ let P; const build=()=>{ h.innerHTML=''; P=pile(h,[3,5,2],{take(){}}); P.box.querySelectorAll('.ls-tok').forEach(t=>t.disabled=true); a.note('Your move.'); }; build();
   return {reset:build, async show(){ await sleep(300); a.note('Taking the top two tokens of the middle pile…'); await leave(P,1,2); P.box.querySelectorAll('.ls-tok').forEach(t=>t.disabled=true); a.note('<b>The middle pile went from 5 to 3.</b> The other piles did not change.'); await sleep(1300); a.note('Now your opponent takes the whole last pile…'); await leave(P,2,2); P.box.querySelectorAll('.ls-tok').forEach(t=>t.disabled=true); a.note('<b>Your opponent took all 2.</b> Taking a whole pile is allowed.'); }}; }},
 {kind:'try',title:'Try taking from one pile',text:'Click a token. <b>It and every token above it</b> are taken from that pile.',mount(h,a){ let done=false; const P=pile(h,[3,5,2],{take(i,n,st,r){ if(done) return; done=true; const before=st[i]; st[i]-=n; r(); a.note(`<b>You took ${n} from pile ${i+1}.</b> It went from ${before} to ${st[i]}. Only that pile changed.`); a.ok(); }}); a.note('Choose any token.'); return {async show(){ P.box.querySelectorAll('.ls-pile')[1].querySelectorAll('.ls-tok')[2].click(); }}; }},
 {kind:'cant',title:'Only one pile per turn',text:'You took from one pile. Now <b>try taking from another pile in the same turn</b>.',mount(h,a){ let first=-1, done=false; const P=pile(h,[3,5,2],{take(i,n,st,r,t){ if(done) return; if(first<0){ first=i; st[i]-=n; r(); a.note(`You took ${n} from pile ${i+1}. Now try a token in a different pile.`); return; } if(i===first){ deny(t,a,'Still the same turn. Try a <b>different</b> pile.'); return; } done=true; deny(P.box.querySelectorAll('.ls-pile')[i],a,`<b>Not allowed.</b> A turn takes from exactly one pile, so your turn ended after pile ${first+1}. Pile ${i+1} has to wait for a later turn.`); a.ok(); }}); a.note('Take from any pile first.'); return {async show(){ P.box.querySelectorAll('.ls-pile')[0].querySelectorAll('.ls-tok')[2].click(); await sleep(700); P.box.querySelectorAll('.ls-pile')[1].querySelectorAll('.ls-tok')[4].click(); }}; }},
 {kind:'end',title:'The last token decides',text:'Taking the last token <b>wins</b> in normal Nim. In <b>misère</b> Nim the same move <b>loses</b>. You choose the rule before you start.',mount(h,a){
   /* the rule this player picked (the live game's, else the setup's), so the ending shown is the one they will play */
   const mis=!!(window.ZFA&&ZFA.nimMisere&&ZFA.nimMisere());
   const rule=mis?'Misère: the last token loses':'Normal: the last token wins';
   let P, done=false; const build=()=>{ h.innerHTML=''; done=false; h.appendChild($('div','ls-rulechip',`Your rule · <b>${rule}</b>`));
     P=pile(h,[0,1,0],{take(i,n,st,r){ if(done) return; done=true; st[i]=0; r(); P.box.querySelectorAll('.ls-tok').forEach(t=>t.disabled=true);
       h.appendChild($('div','ls-outcome '+(mis?'lose':'win'),mis?'<b>You lose.</b> You took the last token, and in misère that loses.':'<b>You win.</b> You took the last token, and in normal Nim that wins.'));
       a.note(mis?'In normal Nim this same move would have won. Only the rule differs.':'In misère Nim this same move would have lost. Only the rule differs.'); a.ok(); }});
     a.note('All piles are empty but one, with a single token. Take it.'); };
   build(); return {reset:build, async show(){ await sleep(300); a.note('Taking the last token…'); const t=P.box.querySelector('.ls-tok'); if(!t) return; t.classList.add('pv'); await sleep(700); t.click(); }}; }} ]; }

/* ---- chomp ---- */
function chomp(){ const SKULL='<svg viewBox="0 0 24 24" width="22" height="22"><path fill="currentColor" fill-rule="evenodd" d="M12 2C7.6 2 4.5 5.2 4.5 9.4c0 2.5 1.1 4.1 2.5 5.1V18a1.5 1.5 0 0 0 1.5 1.5h.8V21h2v-1.5h1.4V21h2v-1.5h.8A1.5 1.5 0 0 0 17 18v-3.5c1.4-1 2.5-2.6 2.5-5.1C19.5 5.2 16.4 2 12 2ZM9 9a1.6 1.6 0 1 1 0 3.2A1.6 1.6 0 0 1 9 9Zm6 0a1.6 1.6 0 1 1 0 3.2A1.6 1.6 0 0 1 15 9Z"/></svg>';
 const board=(h,cb)=>{ const R=3,C=4; const g=grid(C); const cells=[]; const gone=new Set(); for(let r=0;r<R;r++)for(let c=0;c<C;c++){ const b=cellBtn(r===0&&c===C-1?SKULL:'','ls-choc',()=>cb(r,c,b)); cells.push(b); g.appendChild(b); } const at=(r,c)=>cells[r*C+c]; h.appendChild(g); return {cells,gone,at,R,C}; };
 const bite=(B,r0,c0)=>{ const hit=[]; for(let r=r0;r<B.R;r++)for(let c=0;c<=c0;c++){ if(!B.gone.has(r*B.C+c)) hit.push([r,c]); } return hit; };
 const eat=(B,hit)=>hit.forEach(([rr,cc])=>{ B.gone.add(rr*B.C+cc); const e=B.at(rr,cc); e.classList.add('gone'); e.disabled=true; });
 return [
 {kind:'goal',title:'Don’t take the poison',text:'A bar of chocolate with one poisoned tile, the skull. <b>Whoever has to take the poison loses.</b>',mount(h,a){ const B=board(h,()=>{}); B.cells.forEach(c=>c.disabled=true); a.note('The poison is always the top-right tile.'); }},
 {kind:'watch',title:'One bite takes a corner',text:'On your turn, choose a tile. <b>It and every tile below it and to its left</b> disappear.',mount(h,a){ let B; const build=()=>{ h.innerHTML=''; B=board(h,()=>{}); B.cells.forEach(c=>c.disabled=true); a.note('Your move.'); }; build();
   return {reset:build, async show(){ await sleep(300); const hit=bite(B,1,1); hit.forEach(([r,c])=>B.at(r,c).classList.add('pv')); a.note('Biting the second tile of the middle row…'); await sleep(900); hit.forEach(([r,c])=>B.at(r,c).classList.remove('pv')); eat(B,hit); a.note(`<b>${hit.length} tiles are gone:</b> the chosen one, plus everything below it and to its left.`); }}; }},
 {kind:'try',title:'Take a bite',text:'Bite the tile in the <b>second row, second column</b>. See exactly what disappears.',mount(h,a){ let done=false; const B=board(h,(r,c,el)=>{ if(done) return; if(r===0&&c===B.C-1){ deny(el,a,'That is the poison. Taking it now would lose at once. Try the dashed tile.'); return; } done=true; const hit=bite(B,r,c); eat(B,hit); a.note(`<b>You bit ${hit.length} tile${hit.length===1?'':'s'}:</b> the one you chose plus everything below it and to its left. The rest stays.`); a.ok(); }); B.at(1,1).classList.add('tgt'); a.note('Choose a tile.'); return {async show(){ B.at(1,1).click(); }}; }},
 {kind:'cant',title:'Eaten tiles are gone',text:'Some tiles have been bitten already. <b>Try biting one of the empty places.</b>',mount(h,a){ let done=false; const B=board(h,(r,c,el)=>{ if(done) return; if(B.gone.has(r*B.C+c)) return; if(r===0&&c===B.C-1){ deny(el,a,'That is the poison. Pick another tile.'); return; } done=true; const hit=bite(B,r,c); eat(B,hit); a.note(`<b>Allowed.</b> Only tiles still on the board can be bitten. This bite took ${hit.length}.`); a.ok(); }); eat(B,bite(B,1,1)); B.cells.forEach((c,k)=>{ if(B.gone.has(k)){ c.disabled=false; c.onclick=()=>{ if(!done) deny(c,a,'<b>Not allowed.</b> That tile was already eaten. Choose a tile that is still there.'); }; } }); a.note('Click an empty place first, then a real tile.'); return {async show(){ B.at(2,0).click(); await sleep(900); B.at(0,1).click(); }}; }},
 {kind:'end',title:'Someone must take the poison',text:'Every bite shrinks the bar. When the poison is the only tile left, <b>the player to move must take it and loses</b>.',mount(h,a){ let done=false; const B=board(h,(r,c)=>{ if(done) return; done=true; a.note('<b>You took the poison, so you lose.</b> Nothing else was left to take. There are no draws in Chomp.'); a.ok(); }); for(let r=0;r<B.R;r++)for(let c=0;c<B.C;c++){ if(!(r===0&&c===B.C-1)) eat(B,[[r,c]]); } a.note('Only the poison is left, and it is your move.'); return {async show(){ B.at(0,B.C-1).click(); }}; }} ]; }

/* ---- quarto ---- */
function quarto(){ const Z=window.ZART; const piece=(p,cls)=>{ const s=document.createElementNS('http://www.w3.org/2000/svg','svg'); s.setAttribute('viewBox','-2 -2 64 84'); if(cls) s.setAttribute('class',cls); s.innerHTML=Z.qPiece(p,0,0,1); s.setAttribute('aria-label',Z.qLabel(p)); s.appendChild(document.createElementNS('http://www.w3.org/2000/svg','title')).textContent=Z.qLabel(p); return s; };
 const NAMES=['tall','short','round','square','light','dark','hollow','solid']; const has=(p,n)=>{ const i=NAMES.indexOf(n); return (((p>>(i>>1))&1)===1)===(i%2===0); };
 const ask=(h,a,ps,goodMsg)=>{ const row=$('div','ls-pieces'); ps.forEach(p=>row.appendChild(piece(p))); h.appendChild(row); const shared=NAMES.filter(n=>ps.every(p=>has(p,n))); const chips=$('div','ls-chips'); const pick=new Set(); NAMES.forEach(n=>{ const b=$('button','ls-chip',n); b.type='button'; b.setAttribute('aria-pressed','false'); b.onclick=()=>{ pick.has(n)?pick.delete(n):pick.add(n); b.setAttribute('aria-pressed',pick.has(n)); }; chips.appendChild(b); }); h.appendChild(chips); const ck=$('button','ls-btn','Check'); ck.type='button'; ck.onclick=()=>{ const ok=pick.size===shared.length&&shared.every(n=>pick.has(n)); chips.querySelectorAll('.ls-chip').forEach(b=>{ b.classList.toggle('ok',shared.includes(b.textContent)); }); row.querySelectorAll('svg').forEach(s=>s.classList.toggle('win',ok)); a.note(ok?goodMsg(shared):`Not quite. They share: <b>${shared.join(', ')}</b>. Everything else differs.`); if(ok) a.ok(); }; h.appendChild(ck); return {async show(){ chips.querySelectorAll('.ls-chip').forEach(b=>{ if(b.getAttribute('aria-pressed')==='true') b.click(); }); shared.forEach(n=>{ [...chips.children].find(b=>b.textContent===n).click(); }); await sleep(250); ck.click(); }}; };
 const qboard=(h,cells)=>{ const g=$('div','ls-qb'); const out=[]; for(let i=0;i<16;i++){ const c=$('div','ls-qc'); if(cells[i]!==undefined) c.appendChild(piece(cells[i])); out.push(c); g.appendChild(c); } h.appendChild(g); return out; };
 return [
 {kind:'goal',title:'Four in a row that share a trait',text:'Sixteen pieces, four traits: <b>tall or short, round or square, light or dark, hollow or solid</b>. Complete a row of four that share <b>any one</b> trait.',mount(h,a){ const ps=[8,9,10,12], cs=qboard(h,{4:8,5:9,6:10,7:12}); [4,5,6,7].forEach(k=>cs[k].classList.add('win')); a.note(`These four are all <b>${NAMES.filter(n=>ps.every(p=>has(p,n))).join(' and ')}</b>, so the row wins, even though they differ in other ways.`); }},
 {kind:'watch',title:'Place, then hand over',text:'Your turn has two parts: <b>place the piece your opponent gave you</b>, then <b>choose the piece they must place</b>.',mount(h,a){ let cs, hand, tray; const build=()=>{ h.innerHTML=''; const top=$('div','ls-qrow'); hand=$('div','ls-qhand'); hand.appendChild(piece(5)); top.append($('span','ls-qlab','Given to you'),hand); h.appendChild(top); cs=qboard(h,{0:15,10:0}); tray=$('div','ls-pieces'); [3,6,12].forEach(p=>tray.appendChild(piece(p))); h.appendChild($('span','ls-qlab','You choose one of these for your opponent')); h.appendChild(tray); a.note('You were handed a piece.'); }; build();
   return {reset:build, async show(){ await sleep(400); const p=hand.firstChild; cs[5].appendChild(p); cs[5].classList.add('last'); sh(cs[5],'ls-pop'); a.note('<b>1. You place the piece you were given</b> on any empty square.'); await sleep(1300); const pick=tray.children[1]; pick.classList.add('win'); a.note('<b>2. You choose the next piece</b> and hand it to your opponent. They must place it.'); await sleep(900); hand.appendChild(pick.cloneNode(true)); pick.style.visibility='hidden'; }}; }},
 {kind:'try',title:'Spot the shared traits',text:'Two pieces. Select <b>every trait</b> they have in common, then Check.',mount(h,a){ a.note('Pick the shared traits.'); return ask(h,a,[3,8],s=>`<b>Yes: only ${s.join(', ')}.</b> One shared trait is enough for four pieces to win.`); }},
 {kind:'try',title:'Different, but connected',text:'Four pieces can look very different and still win, as long as <b>one</b> trait runs through all four.',mount(h,a){ a.note('Which trait do all four share?'); return ask(h,a,[8,9,10,12],s=>`<b>All four are ${s.join(' and ')}.</b> A row of these wins.`); }},
 {kind:'cant',title:'Never hand over a winner',text:'Your opponent places <b>the piece you choose</b>. If it completes a line for them, you have just given away the game.',mount(h,a){ const d=ZFX.def&&ZFX.def('quarto'); if(d&&d.demo){ const box=$('div'); box.style.cssText='width:100%'; h.appendChild(box); d.demo(box,{}); box.querySelectorAll('.gx-tag,.gx-btn').forEach(x=>x.style.display='none'); const n=box.querySelector('.gx-note'); if(n) n.style.display='none'; const obs=new MutationObserver(()=>{ a.note(n?n.innerHTML:''); if(n&&n.textContent.length>20) a.ok(); }); if(n) obs.observe(n,{childList:true,subtree:true,characterData:true}); a.note(n?n.innerHTML:'Place the highlighted piece.'); return {async show(){ const c=box.querySelector('.qz-cell:not(:disabled)'); if(c) c.click(); }}; } }},
 {kind:'end',title:'How it ends',text:'The player who places the fourth piece of a sharing line <b>wins</b>, whoever chose it. If all sixteen squares fill with no such line, <b>it is a draw</b>.',mount(h,a){ const ps=[12,13,14,15], cs=qboard(h,{0:12,5:13,10:14,15:15}); [0,5,10,15].forEach(k=>cs[k].classList.add('win')); a.note(`Diagonals count too: these four are all <b>${NAMES.filter(n=>ps.every(p=>has(p,n))).join(' and ')}</b>.`); }} ]; }

/* ---- sim ---- */
function sim(){ const V=(k,n=6)=>{ const a=-Math.PI/2+k*2*Math.PI/n; return [140+96*Math.cos(a),110+96*Math.sin(a)]; };
 const board=(h,mine,theirs,onEdge)=>{ const NS='http://www.w3.org/2000/svg'; const s=document.createElementNS(NS,'svg'); s.setAttribute('viewBox','0 0 280 220'); s.setAttribute('class','ls-svg'); const all=[]; for(let i=0;i<6;i++)for(let j=i+1;j<6;j++) all.push([i,j]); const own=(e,L)=>L.some(x=>x[0]===e[0]&&x[1]===e[1]);
  let html=''; all.forEach(e=>{ const [x1,y1]=V(e[0]),[x2,y2]=V(e[1]); const m=own(e,mine), t=own(e,theirs); html+=`<line data-e="${e[0]}-${e[1]}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="${m||t?6:2}" stroke-opacity="${m||t?1:.2}" ${t?'stroke-dasharray="10 8"':''} stroke-linecap="round"/>`; });
  s.innerHTML=html+'<g class="tri"></g>'+all.map(([i,j])=>{ const [x1,y1]=V(i),[x2,y2]=V(j); return `<line class="h" data-e="${i}-${j}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="transparent" stroke-width="22" style="cursor:pointer"/>`; }).join('')+[...Array(6).keys()].map(k=>{ const [x,y]=V(k); return `<circle cx="${x}" cy="${y}" r="11" fill="var(--surf2)" stroke="currentColor" stroke-width="3"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="11" font-weight="700" fill="currentColor">${k+1}</text>`; }).join('');
  s.querySelectorAll('.h').forEach(l=>l.onclick=()=>onEdge&&onEdge(l.dataset.e.split('-').map(Number),s)); h.appendChild(s); return s; };
 const claim=(s,e,dash)=>{ const l=s.querySelector(`line[data-e="${e[0]}-${e[1]}"]:not(.h)`); l.setAttribute('stroke-width','6'); l.setAttribute('stroke-opacity','1'); if(dash) l.setAttribute('stroke-dasharray','10 8'); };
 const tri=(s,a,b,c)=>{ s.querySelector('.tri').innerHTML=`<polygon points="${[V(a),V(b),V(c)].map(p=>p.join(',')).join(' ')}" fill="currentColor" fill-opacity=".18"/>`; };
 const key=e=>e[0]+'-'+e[1];
 return [
 {kind:'goal',title:'Don’t complete a triangle',text:'Six dots. Players take turns claiming the lines between them. <b>If three of your own lines form a triangle, you lose.</b>',mount(h,a){ const s=board(h,[[0,2],[2,4],[0,4]],[[1,3],[3,5]]); tri(s,0,2,4); a.note('Solid lines are one player, dashed lines the other. Solid has closed a triangle, so solid loses.'); }},
 {kind:'watch',title:'Claim one line',text:'On your turn, claim <b>one unclaimed line</b> between two dots.',mount(h,a){ let s; const build=()=>{ h.innerHTML=''; s=board(h,[],[]); a.note('Your move.'); }; build();
   return {reset:build, async show(){ await sleep(300); claim(s,[0,3]); a.note('<b>You claim the line from dot 1 to dot 4</b> (solid).'); await sleep(1300); claim(s,[1,2],true); a.note('<b>Your opponent claims dot 2 to dot 3</b> (dashed). Lines stay with whoever claimed them.'); }}; }},
 {kind:'try',title:'Claim a safe line',text:'You own two solid lines. <b>Claim any line that does not finish a triangle of yours.</b>',mount(h,a){ let done=false; const mine=[[0,2],[2,4]], theirs=[[1,5]]; const s=board(h,mine,theirs,(e,sv)=>{ if(done) return; const k=key(e); if(mine.concat(theirs).some(x=>key(x)===k)){ deny(null,a,'That line is already claimed. Choose a faint one.'); return; } if(k==='0-4'){ a.note('<b>Careful:</b> 1 to 5 would close your triangle 1-3-5 and lose. Pick another line.'); return; } done=true; claim(sv,e); a.note(`<b>Safe.</b> Dot ${e[0]+1} to dot ${e[1]+1} makes no triangle of three solid lines.`); a.ok(); }); a.note('Choose a faint line.'); return {async show(){ s.querySelector('.h[data-e="0-3"]').dispatchEvent(new MouseEvent('click')); }}; }},
 {kind:'cant',title:'Crossings are not dots',text:'Long lines cross in the middle. <b>Try claiming the crossing point.</b>',mount(h,a){ let done=false; const s=board(h,[[0,3]],[[1,4]]); const c=document.createElementNS('http://www.w3.org/2000/svg','circle'); c.setAttribute('cx',140); c.setAttribute('cy',110); c.setAttribute('r',16); c.setAttribute('fill','transparent'); c.setAttribute('stroke','currentColor'); c.setAttribute('stroke-dasharray','3 4'); c.style.cursor='pointer'; c.onclick=()=>{ if(done) return; done=true; a.note('<b>Not a dot.</b> A crossing cannot be claimed and never makes a triangle. Only the six numbered dots count.'); a.ok(); }; s.appendChild(c); a.note('Click the dashed circle where the lines cross.'); return {async show(){ c.dispatchEvent(new MouseEvent('click')); }}; }},
 {kind:'end',title:'Closing your own triangle loses',text:'The game ends the moment someone completes a triangle of their own lines. <b>That player loses.</b> With six dots, someone always does, so there are no draws.',mount(h,a){ let done=false; const E2=x=>x.map(k=>k.split('-').map(Number)); const mine=E2(['1-3','1-5','0-2','1-2','0-3','4-5']), theirs=E2(['2-5','1-4','3-4','3-5','2-4','0-4','0-5']); const s=board(h,mine,theirs,(e,sv)=>{ if(done) return; const k=key(e); if(mine.concat(theirs).some(x=>key(x)===k)){ deny(null,a,'That line is taken.'); return; } done=true; claim(sv,e); if(k==='0-1'){ tri(sv,0,1,2); a.note('<b>That completes your triangle 1-2-3. You lose.</b>'); } else { tri(sv,1,2,3); a.note('<b>That completes your triangle 2-3-4. You lose.</b>'); } a.ok(); }); a.note('Only two faint lines are left, and both finish a triangle of yours. Claim one.'); return {async show(){ s.querySelector('.h[data-e="0-1"]').dispatchEvent(new MouseEvent('click')); }}; }} ]; }

/* ---- the engine-driven games: practice on the real board, drawn by the game's own renderer ---- */
const reg=id=>window.ZFX&&ZFX.def(id);
const real=(id,h,st,play,extra)=>{ const box=$('div','ls-real'); h.appendChild(box); const d=reg(id); d.render(box,st,Object.assign({human:!st.over,humanIs:1,opp:'2p',opt:{},play},extra||{})); return box; };
/* Pentago */
function pentago(){ const P=ZF_E.PENTAGO; const from=seq=>{ let s=P.newState(); for(const m of seq) s=P.apply(s,m); return s; };
 const near=from([{t:'place',cell:14},{t:'rot',q:1,d:1},{t:'place',cell:9},{t:'rot',q:0,d:1},{t:'place',cell:6},{t:'rot',q:0,d:-1},{t:'place',cell:21},{t:'rot',q:1,d:1},{t:'place',cell:15},{t:'rot',q:2,d:1},{t:'place',cell:6},{t:'rot',q:3,d:1},{t:'place',cell:16},{t:'rot',q:1,d:1},{t:'place',cell:33},{t:'rot',q:2,d:-1}]);
 return [
 {kind:'goal',title:'Five in a row',text:'Four quadrants make a 6×6 board. <b>Five of your marbles in a line</b>, across, down or diagonally, wins.',mount(h,a){ let s=P.newState(); [0,1,2,3,4].forEach((c,k)=>{ s.cells[c]=1; }); [6,7,13,20].forEach(c=>s.cells[c]=2); s.over=true; s.winner=1; s.lines=[[0,1,2,3,4]]; real('pentago',h,s,()=>{}); a.note('Light has five across the top, so light wins.'); }},
 {kind:'watch',title:'Place, then twist',text:'Every turn has <b>two steps</b>: <b>1.</b> place a marble in any empty hole, <b>2.</b> turn any one quadrant a quarter turn.',mount(h,a){ let s, box; const draw=()=>{ h.innerHTML=''; box=real('pentago',h,s,()=>{},{human:false}); }; const build=()=>{ s=from([{t:'place',cell:7},{t:'rot',q:3,d:1},{t:'place',cell:28},{t:'rot',q:2,d:1}]); draw(); a.note('Light to move.'); }; build();
   return {reset:build, async show(){ await sleep(400); s=P.apply(s,{t:'place',cell:8}); draw(); a.note('<b>Step 1: place.</b> Light puts a marble in an empty hole.'); await sleep(1400); s=P.apply(s,{t:'rot',q:1,d:1}); draw(); a.note('<b>Step 2: twist.</b> Light turns the top-right quadrant clockwise. The marbles in it move with it. Then it is dark’s turn.'); }}; }},
 {kind:'try',title:'Place a marble, then rotate a quadrant',text:'Your turn: <b>place a marble</b> in any hole, then <b>turn any quadrant</b> with its arrows.',mount(h,a){ let s=from([{t:'place',cell:7},{t:'rot',q:3,d:1},{t:'place',cell:28},{t:'rot',q:2,d:1}]), fin=false; const draw=()=>{ h.innerHTML=''; real('pentago',h,s,m=>{ if(fin) return; s=P.apply(s,m); if(m.t==='place'){ draw(); a.note('<b>Step 1 done.</b> Now tap an arrow on any quadrant to turn it.'); } else { fin=true; draw(); a.note('<b>Both steps done.</b> One marble, one twist: that is a whole turn.'); a.ok(); } },{human:!fin}); }; draw(); a.note('Step 1: place a marble in any empty hole.'); return {async show(){ const c=h.querySelector('.pgcell[data-i="14"]'); if(c) c.dispatchEvent(new MouseEvent('click',{bubbles:true})); await sleep(900); const b=h.querySelector('.pgbtn.on[data-q="1"][data-d="1"]'); if(b) b.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }},
 {kind:'cant',title:'You can’t skip the twist',text:'After placing, <b>try placing a second marble</b> instead of turning a quadrant.',mount(h,a){ let s=from([{t:'place',cell:7},{t:'rot',q:3,d:1},{t:'place',cell:28},{t:'rot',q:2,d:1},{t:'place',cell:14}]); let done=false; const draw=()=>{ h.innerHTML=''; const box=real('pentago',h,s,m=>{ if(done) return; s=P.apply(s,m); done=true; draw(); a.note('<b>Turn complete.</b> The twist is not optional: a quadrant turns every single turn, even one with no marbles in it.'); a.ok(); }); const svg=box.querySelector('svg'); if(svg&&!done) svg.addEventListener('click',e=>{ if(e.target.closest('.pgbtn')) return; deny(box.querySelector('.pg'),a,'<b>Not allowed yet.</b> You already placed your marble this turn. Finish the turn by turning a quadrant with an arrow.'); }); }; draw(); a.note('You just placed the marble in the top-right quadrant. Tap an empty hole.'); return {async show(){ const b=h.querySelector('.pgbtn.on[data-q="0"][data-d="1"]'); if(b) b.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }},
 {kind:'end',title:'A twist can finish the line',text:'Five in a row wins, <b>even when the twist makes it</b>. If one twist makes five for both players, or the board fills, <b>it is a draw</b>.',mount(h,a){ let s=near; const al=[{cell:12}]; const draw=()=>{ h.innerHTML=''; real('pentago',h,s,m=>{ s=P.apply(s,m); draw(); if(s.over){ a.note('<b>Five in a row.</b> The turn slid a marble into the gap, so light wins.'); a.ok(); } else if(s.phase==='rot'){ a.note('Now turn the top-right quadrant counter-clockwise (the arrow on its top left).'); } },{allowed:s.phase==='place'?{cell:12}:{rot:{q:1,d:-1}},human:!s.over}); }; draw(); a.note('Place a marble in the dashed hole.'); return {async show(){ const c=h.querySelector('.pgcell[data-i="12"]'); if(c) c.dispatchEvent(new MouseEvent('click',{bubbles:true})); await sleep(900); const b=h.querySelector('.pgbtn.on'); if(b) b.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }} ]; }
/* TOOT & OTTO */
function toot(){ const T=ZF_E.TOOT; const from=seq=>{ let s=T.newState(); for(const [ch,col] of seq) s=T.apply(s,{ch,col}); return s; };
 return [
 {kind:'goal',title:'Spell your word',text:'Player 1 wants <b>TOOT</b>, Player 2 wants <b>OTTO</b>. Four letters in a line, across, down or diagonally, spell a word.',mount(h,a){ const s=from([['T',0],['O',5],['O',1],['O',4],['O',2],['T',5],['T',3]]); real('toot',h,s,()=>{}); a.note('TOOT along the bottom row: Player 1 wins.'); }},
 {kind:'watch',title:'Drop one letter',text:'On your turn, choose <b>T or O</b> and drop it in a column. It falls to the lowest empty space.',mount(h,a){ let s; const draw=()=>{ h.innerHTML=''; real('toot',h,s,()=>{},{human:false}); }; const build=()=>{ s=from([['T',2],['O',2]]); draw(); a.note('Player 1 to move.'); }; build();
   return {reset:build, async show(){ await sleep(400); s=T.apply(s,{ch:'O',col:2}); draw(); a.note('<b>Player 1 drops an O in column 3.</b> It lands on top of the letters already there.'); await sleep(1400); s=T.apply(s,{ch:'T',col:4}); draw(); a.note('<b>Player 2 drops a T in column 5.</b> Each player has six of each letter.'); }}; }},
 {kind:'try',title:'Drop a letter',text:'Pick <b>T or O</b>, then click a column.',mount(h,a){ let s=from([['T',2],['O',2]]); let done=false; const draw=()=>{ h.innerHTML=''; real('toot',h,s,m=>{ if(done) return; done=true; s=T.apply(s,m); draw(); a.note(`<b>Your ${m.ch} fell to the lowest free space in column ${m.col+1}.</b> Now it would be your opponent’s turn.`); a.ok(); },{human:!done}); }; draw(); a.note('Choose a letter, then a column.'); return {async show(){ const c=h.querySelector('.tt-cell.hit[data-col="0"]'); if(c) c.click(); }}; }},
 {kind:'cant',title:'Their word counts, whoever spells it',text:'It does not matter <b>who dropped the letters</b>. You want TOOT: drop an <b>O</b> in column 4 and see.',mount(h,a){ let s=from([['O',0],['T',1],['T',2],['T',5]]); let done=false; const draw=()=>{ h.innerHTML=''; real('toot',h,s,m=>{ if(done) return; s=T.apply(s,m); draw(); if(s.over&&s.winner===2){ done=true; a.note('<b>OTTO.</b> Your own drop spelled your opponent’s word, so <b>they</b> win. Never complete their word.'); a.ok(); } else { a.note('Nothing spelled. Reset with Try again and drop an <b>O</b> in column 4.'); done=true; } },{human:!done}); }; draw(); a.note('You are Player 1 (TOOT). Drop an O in column 4.'); return {async show(){ const o=h.querySelector('.tt-pick button[data-l="O"]'); if(o) o.click(); await sleep(250); const c=h.querySelector('.tt-cell.hit[data-col="3"]'); if(c) c.click(); }}; }},
 {kind:'end',title:'How it ends',text:'The first word to appear wins for whoever owns it. A drop that spells <b>both</b> words, or a full board with neither, <b>is a draw</b>.',mount(h,a){ const s=from([['T',0],['O',5],['O',1],['O',4],['O',2],['T',5],['T',3]]); real('toot',h,s,()=>{}); a.note('The game stops the moment a word appears.'); }} ]; }
/* Notakto */
function notakto(){ const N=ZF_E.NOTAKTO; const from=(seq,n)=>{ let s=N.newState(n||3); for(const [b,c] of seq) s=N.apply(s,{b,c}); return s; };
 return [
 {kind:'goal',title:'Don’t close the last board',text:'Both players place <b>X</b>. Three in a row <b>closes</b> that board. <b>Whoever closes the last open board loses.</b>',mount(h,a){ const s=from([[0,0],[0,1],[0,2],[1,4],[2,0],[2,4]]); real('notakto',h,s,()=>{},{human:false}); a.note('The first board is closed. Two remain open.'); }},
 {kind:'watch',title:'Place one X',text:'On your turn, put <b>one X</b> on any empty cell of any open board.',mount(h,a){ let s; const draw=()=>{ h.innerHTML=''; real('notakto',h,s,()=>{},{human:false}); }; const build=()=>{ s=from([]); draw(); a.note('Player 1 to move.'); }; build();
   return {reset:build, async show(){ await sleep(400); s=N.apply(s,{b:1,c:4}); draw(); a.note('<b>Player 1 marks the centre of board 2.</b>'); await sleep(1300); s=N.apply(s,{b:0,c:0}); draw(); a.note('<b>Player 2 also places an X</b>, on board 1. Marks belong to nobody.'); }}; }},
 {kind:'try',title:'Place an X',text:'Click <b>any empty cell</b> on any open board.',mount(h,a){ let s=from([[1,4]]); let done=false; const draw=()=>{ h.innerHTML=''; real('notakto',h,s,m=>{ if(done) return; done=true; s=N.apply(s,m); draw(); a.note(`<b>Placed on board ${m.b+1}.</b> Now the other player moves.`); a.ok(); },{human:!done}); }; draw(); a.note('Choose a cell.'); return {async show(){ const c=h.querySelector('.c[tabindex]'); if(c) c.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }},
 {kind:'cant',title:'Closed boards are finished',text:'Board 1 is closed. <b>Try placing an X on it.</b>',mount(h,a){ let s=from([[0,0],[0,4],[0,8],[1,4]]); let done=false; const draw=()=>{ h.innerHTML=''; const box=real('notakto',h,s,m=>{ if(done) return; done=true; s=N.apply(s,m); draw(); a.note('<b>Allowed.</b> Open boards take moves; closed ones never do.'); a.ok(); },{human:!done}); const cl=box.querySelector('.nk-b.closed'); if(cl&&!done){ cl.style.cursor='pointer'; cl.addEventListener('click',()=>deny(cl,a,'<b>Not allowed.</b> A closed board takes no more moves. Play on an open board.')); } }; draw(); a.note('Try the closed board, then an open one.'); return {async show(){ const cl=h.querySelector('.nk-b.closed'); if(cl) cl.click(); await sleep(900); const c=h.querySelector('.c[tabindex]'); if(c) c.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }},
 {kind:'end',title:'The last line loses',text:'Closing an early board is legal and can be smart. <b>The player who closes the last open board loses.</b> There are no draws.',mount(h,a){ let s=from([[0,0],[0,4],[0,8],[1,0],[1,4],[1,8],[2,0],[2,1]]); let done=false; const draw=()=>{ h.innerHTML=''; real('notakto',h,s,m=>{ if(done) return; s=N.apply(s,m); draw(); if(s.over){ done=true; a.note('<b>You closed the last board, so you lose.</b>'); a.ok(); } else a.note('Safe for now. Try completing the top row of board 3.'); },{human:!done}); }; draw(); a.note('One board is left. Complete its top row.'); return {async show(){ const c=h.querySelector('.c[data-b="2"][data-c="2"]'); if(c) c.dispatchEvent(new MouseEvent('click',{bubbles:true})); }}; }} ]; }

/* ---- domineering: the two players have different orientations, and the practice alternates them ---- */
function domineering(){ const E=ZF_E.DOM;
 const after=(seq,R,C,holes)=>{ let st=E.newState(R||4,C||4,holes||[]); for(const [r,c] of seq) st=E.apply(st,{r,c}); return st; };
 return [
 {kind:'goal',title:'Leave your opponent stuck',text:'One player places <b>vertical</b> dominoes, the other <b>horizontal</b> ones. Each domino covers two empty squares. <b>If you cannot place a domino on your turn, you lose.</b>',mount(h,a){ const st=after([[0,1],[3,1],[1,3]]); real('domineering',h,st,()=>{},{human:false}); a.note('Solid tiles stand up (Player 1, vertical). Outlined tiles lie flat (Player 2, horizontal).'); }},
 {kind:'watch',title:'Players take turns, each in their own direction',text:'Player 1 places a domino <b>standing up</b>. Then Player 2 places one <b>lying flat</b>. Turns alternate.',mount(h,a){ let st; const draw=()=>{ h.innerHTML=''; real('domineering',h,st,()=>{},{human:false}); }; const build=()=>{ st=E.newState(4,4); draw(); a.note('Player 1 (vertical) to move.'); }; build();
   return {reset:build, async show(){ await sleep(400); st=E.apply(st,{r:0,c:1}); draw(); a.note('<b>Player 1 places a vertical domino</b>: two squares, one above the other.'); await sleep(1500); st=E.apply(st,{r:3,c:1}); draw(); a.note('<b>Player 2 places a horizontal domino</b>: two squares side by side.'); }}; }},
 {kind:'try',title:'Place a vertical, then a horizontal domino',text:'You play both sides in this practice. The status line says <b>whose turn it is and which way they place</b>.',mount(h,a){ let st=E.newState(4,4,[10]); let n=0; const say=()=>{ const v=st.turn===1; return `<b>Player ${st.turn}’s turn: place a ${v?'vertical':'horizontal'} domino.</b> ${v?'It covers a square and the one below it.':'It covers a square and the one to its right.'}`; };
   const draw=()=>{ h.innerHTML=''; const head=$('div','ls-turn',`<span class="ls-dir ${st.turn===1?'v':'h'}"></span>${st.over?'Practice over':`Player ${st.turn} · ${st.turn===1?'vertical':'horizontal'}`}`); h.appendChild(head); real('domineering',h,st,m=>{ st=E.apply(st,m); n++; draw(); if(st.over){ a.note(`<b>Player ${st.trap.loser} has no ${st.trap.loser===1?'vertical':'horizontal'} space left, so Player ${st.winner} wins.</b>`); a.ok(); } else if(n===1) a.note('<b>Vertical placed.</b> Now it is Player 2’s turn, and Player 2 places <b>horizontally</b>. '+say()); else if(n===2){ a.note('<b>Horizontal placed.</b> That is one full round. Keep going, or press Next. '+say()); a.ok(); } else a.note(say()); },{human:!st.over}); }; draw(); a.note(say()); return {async show(){ let c=h.querySelector('.dmhit[data-r="0"][data-c="0"]'); if(c) c.dispatchEvent(new MouseEvent('click')); await sleep(1000); c=h.querySelector('.dmhit[data-r="3"][data-c="2"]'); if(c) c.dispatchEvent(new MouseEvent('click')); }}; }},
 {kind:'cant',title:'Two empty squares, or nothing',text:'A domino needs <b>two adjacent empty squares in your direction</b>. It cannot overlap a piece, cover a blocked square (crossed out), or hang off the board. Tap a square where nothing fits.',mount(h,a){ let st=after([[0,0],[3,0]],4,4,[6]); st.turn=1; let tries=0, done=false; const draw=()=>{ h.innerHTML=''; h.appendChild($('div','ls-turn','<span class="ls-dir v"></span>Player 1 · vertical')); const box=real('domineering',h,st,m=>{ if(done) return; done=true; st=E.apply(st,m); draw(); a.note('<b>That one fits:</b> two empty squares, one above the other.'+(tries?'':' Now press Try again and tap a square where nothing fits.')); if(tries) a.ok(); }); box.querySelectorAll('.dmhit[tabindex="-1"]').forEach(el=>el.addEventListener('click',()=>{ if(done) return; tries++; const r=+el.dataset.r, c=+el.dataset.c, i=r*4+c; const below=r+1<4?st.cells[i+4]:null; const why=r===3?'there is no square below it on the board':below===9?'the square below it is blocked':'the square below it is already covered'; deny(el.closest('.dm'),a,`<b>Nothing fits there:</b> a vertical domino needs the square below too, and ${why}. Now place one where it fits.`); })); }; draw(); a.note('Tap the square just above the crossed-out one, or the bottom row.'); return {async show(){ const bad=h.querySelector('.dmhit[data-r="0"][data-c="2"]'); if(bad) bad.dispatchEvent(new MouseEvent('click')); await sleep(1100); const ok=h.querySelector('.dmhit[data-r="0"][data-c="3"]'); if(ok) ok.dispatchEvent(new MouseEvent('click')); }}; }},
 {kind:'end',title:'No room in your direction? You lose',text:'Free squares are not enough: <b>they have to be the right shape</b>. Leave Player 2 with no two free squares side by side.',mount(h,a){ let st=after([[0,1],[3,1],[2,0],[2,1]]); let done=false; const draw=()=>{ h.innerHTML=''; h.appendChild($('div','ls-turn','<span class="ls-dir v"></span>Player 1 · vertical')); real('domineering',h,st,m=>{ if(done) return; const n=E.apply(st,m); if(!n.over){ a.note('Legal, but Player 2 could still answer. Look for the top-right corner.'); return; } done=true; st=n; draw(); a.note(`<b>Player 2 has ${st.trap.empties.length} free squares (dashed) but no two side by side.</b> No horizontal domino fits, so Player 2 loses.`); a.ok(); },{human:!done}); }; draw(); a.note('Your move, vertical. Find the placement that leaves Player 2 nothing.'); return {async show(){ const c=h.querySelector('.dmhit[data-r="0"][data-c="3"]'); if(c) c.dispatchEvent(new MouseEvent('click')); }}; }} ]; }

/* ---- the two original games ---- */
function crowd(){ return [
 {kind:'goal',title:'The goal',text:'Each night you decide, at the same time as everyone else, whether to <b>go out or stay home</b>. The room has 18 places. Go and it is not over capacity: +3. Go and it is: −2. Stay home: +1.',mount(h,a){ const r=$('div','ls-room'); r.innerHTML='<div class="ls-day"><i>Places</i><b>18</b>the room is comfortable up to here</div><div class="ls-day"><i>Score</i><b>+3 / −2 / +1</b>go, crowded, stay</div>'; h.appendChild(r); }},
 {kind:'try',title:'Try this',text:'Last night is history. <b>Tonight is unknown.</b> Choose.',mount(h,a){ const box=$('div','ls-room'); box.innerHTML='<div class="ls-day past"><i>Last night</i><b>13 came</b>a quiet night</div><div class="ls-day"><i>Tonight</i><b>?</b>nobody knows yet</div>'; h.appendChild(box); const row=$('div','ls-chips'); const go=$('button','ls-btn','Go out'), stay=$('button','ls-btn ghost','Stay home'); go.type=stay.type='button'; row.append(go,stay); h.appendChild(row); const res=$('div','ls-lines'); h.appendChild(res); let done=false; const play=async(went)=>{ if(done) return; done=true; row.style.display='none'; box.children[1].innerHTML='<i>Tonight</i><b>19 came</b>'+(went?'including you':'without you'); const att=19; const lines=[went?'You went.':'You stayed home.',`${att} people arrived for 18 places.`, went?'Too crowded: −2 points.':'You avoided a crowded room: +1 point.']; for(const l of lines){ res.appendChild($('div','',l)); await sleep(650); } a.note('Everyone who saw a quiet night decided to go. That is why yesterday’s crowd is a poor guide to tomorrow’s.'); a.ok(); }; go.onclick=()=>play(true); stay.onclick=()=>play(false); return {async show(){ stay.click(); }}; }},
 {kind:'rule',title:'One complication',text:'Other guests follow simple rules of their own, such as “go if last night was quiet”. <b>Because they react to yesterday, yesterday stops being a good guide.</b>',mount(h,a){ const r=$('div','ls-room'); r.innerHTML='<div class="ls-day past"><i>Night 1</i><b>13</b>quiet → many go</div><div class="ls-day"><i>Night 2</i><b>19</b>crowded → many stay</div>'; h.appendChild(r); a.note('In the game you can click any guest to read their rule.'); }} ]; }

function message(){ const Z=window.ZART; const W0=Z.msgWorld(); const scene=(o)=>{ const W=W0; return `<svg viewBox="0 46 256 160" style="width:min(100%,360px);height:auto;color:var(--fg)">${W.markup}${Z.lamp(W.ax,W.ay,!!o.a,'')}${Z.lamp(W.bx,W.by,!!o.b,'')}${o.q?`<text x="${W.ax}" y="${W.qy}" text-anchor="middle" font-size="24" font-weight="800" fill="currentColor">?</text>`:''}${o.env||''}${o.reveal?'<text x="128" y="64" text-anchor="middle" font-size="9" font-weight="700" fill="currentColor" fill-opacity=".7" font-family="var(--font-mono)">EXPLANATION: BOTH SIDES SHOWN</text>':''}<text x="44" y="196" text-anchor="middle" font-size="10.5" font-weight="700" fill="currentColor" font-family="var(--font-mono)">HILL (you)</text><text x="214" y="196" text-anchor="middle" font-size="10.5" font-weight="700" fill="currentColor" font-family="var(--font-mono)">HARBOR</text></svg>`; };
 return [
 {kind:'goal',title:'The goal',text:'Hill and Harbor must attack at dawn <b>together</b>. Both attack: +8. Both wait: 0. <b>Only one attacks: −10.</b> Hill can send a messenger, but it might be lost.',mount(h,a){ h.innerHTML+=scene({}); a.note('Harbor’s rule is public: if a GO reaches it, it attacks at dawn. Otherwise it waits.'); }},
 {kind:'try',title:'Try this',text:'You sent GO. <b>What do you know?</b> Decide before anything is revealed.',mount(h,a){ const box=$('div'); box.innerHTML=scene({q:true,env:Z.messenger(110,W0.lane,'GO','')}); h.appendChild(box); const row=$('div','ls-chips'); const act=$('button','ls-btn','Attack at dawn'), wait=$('button','ls-btn ghost','Wait'); act.type=wait.type='button'; row.append(act,wait); h.appendChild(row); a.note('Hill only knows it sent GO. It cannot see whether GO arrived.'); const res=$('div','ls-lines'); h.appendChild(res); let done=false; const reveal=async(attack)=>{ if(done) return; done=true; row.style.display='none'; box.innerHTML=scene({a:attack,b:true,q:false,reveal:true}); res.innerHTML='<div>Now the truth: GO <b>arrived</b>, so Harbor attacked.</div>'; await sleep(600); res.innerHTML+=`<div>${attack?'Both attacked: +8, minus 1 for the message.':'Hill waited, Harbor attacked alone: −10, minus 1.'}</div>`; await sleep(600); res.innerHTML+='<div><b>Hill knew:</b> it sent GO. <b>Harbor knew:</b> GO arrived.</div>'; a.note('Two different pictures of the same night: what happened, and what each side knew.'); a.ok(); }; act.onclick=()=>reveal(true); wait.onclick=()=>reveal(false); return {async show(){ act.click(); }}; }},
 {kind:'rule',title:'One complication',text:'An acknowledgment tells Hill more, but then <b>Harbor cannot know whether its reply arrived</b>. Every extra message can be lost too.',mount(h,a){ h.innerHTML+=scene({a:false,b:true,env:Z.messenger(150,W0.lane,'OK','')}); a.note('Hill receives RECEIVED and knows GO arrived. Harbor still does not know that Hill knows.'); }} ]; }

/* ---- the gold coin game: six steps on a private demonstration board, then the strategy, discovered ---- */
function gold(){ let A=null; const G=window.ZF_E.GOLD, Z=window.ZART; const CW=46, PAD=10, CY=44, R=13, RK=k=>Z.coinR(k,R);
 /* a demonstration board with its own state. It never touches the live game. hooks: move(m,before,after,api), variant */
 const track=(h,o)=>{ let s=G.newState({n:o.n,pens:o.pens,gold:o.gold,variant:o.variant||'std'}); const start=s; let sel=null, dead=false; const wrap=$('div','ls-gt'); const view=$('div','ls-gtv'); const bar=$('div','ls-gbar'); wrap.append(view,bar); h.appendChild(wrap);
  const W=o.n*CW+PAD*2, cx=p=>PAD+p*CW+CW/2;
  const draw=()=>{ const L=dead?[]:G.legal(s); let g=''; for(let p=0;p<o.n;p++) g+=`<rect x="${PAD+p*CW+2}" y="${CY-24}" width="${CW-4}" height="48" rx="9" fill="currentColor" fill-opacity=".09"/><text x="${cx(p)}" y="${CY+42}" text-anchor="middle" font-size="10" font-weight="600" fill="currentColor" fill-opacity=".5" font-family="ui-monospace,monospace">${p+1}</text>`;
   if(o.pairs&&s.coins.length>1){ const P=G.piles(s); P.forEach(p=>{ if(p.kind==='pair'){ const a=s.coins.find(c=>c.id===p.left), b=s.coins.find(c=>c.id===p.right); g+=`<path d="M${cx(a.pos)} ${CY-RK('gold')-6}V${CY-RK('gold')-12}H${cx(b.pos)}V${CY-RK('gold')-6}" fill="none" stroke="currentColor" stroke-width="2"/><text x="${(cx(a.pos)+cx(b.pos))/2}" y="${CY-RK('gold')-16}" text-anchor="middle" font-size="12" font-weight="700" fill="currentColor" font-family="ui-monospace,monospace">${p.h}</text>`; } else if(o.pairs>1){ const a=s.coins.find(c=>c.id===p.coin); g+=`<path d="M${cx(0)-R} ${CY-RK('gold')-6}V${CY-RK('gold')-12}H${cx(a.pos)}V${CY-RK('gold')-6}" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="4 4"/><text x="${(cx(0)+cx(a.pos))/2}" y="${CY-RK('gold')-16}" text-anchor="middle" font-size="12" font-weight="700" fill="currentColor" font-family="ui-monospace,monospace">${p.h}</text>`; } }); }
   s.coins.forEach(c=>{ g+=`<g data-id="${c.id}" style="cursor:${dead?'default':'pointer'}" ${dead?'':'tabindex="0" role="button"'} aria-label="${c.kind==='gold'?'gold coin':'penny'} at space ${c.pos+1}">${Z.coin(c.kind,cx(c.pos),CY,R)}${sel===c.id?`<circle cx="${cx(c.pos)}" cy="${CY}" r="${RK(c.kind)+5}" fill="none" stroke="currentColor" stroke-width="3"/>`:''}</g>`; });
   if(sel) L.filter(m=>m.t==='slide'&&m.id===sel).forEach(m=>{ g+=`<g data-to="${m.to}" style="cursor:pointer" tabindex="0" role="button" aria-label="slide to space ${m.to+1}"><rect x="${PAD+m.to*CW}" y="${CY-26}" width="${CW}" height="52" fill="transparent"/><circle cx="${cx(m.to)}" cy="${CY}" r="${RK((s.coins.find(c=>c.id===sel)||{}).kind)}" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="4 4"/></g>`; });
   if(o.hl) o.hl(s).forEach(p=>{ g+=`<circle cx="${cx(p)}" cy="${CY}" r="${RK('gold')+5}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-dasharray="3 5"/>`; });
   view.innerHTML=`<svg viewBox="0 0 ${W} ${CY+54}" style="width:${Math.min(W,560)}px;max-width:100%;height:auto;color:var(--fg);overflow:visible;display:block">${g}</svg>`;
   bar.innerHTML=''; { const rb=$('button','ls-btn ghost','Reset'); rb.type='button'; rb.onclick=()=>{ api.reset(); if(A) A.note('Reset. Try again.'); }; bar.appendChild(rb); } if(!dead&&s.coins.length){ if(!o.noTake){ const b=$('button','ls-btn ghost','Take leftmost coin'); b.type='button'; b.onclick=()=>go({t:'collect'}); bar.appendChild(b); } if(o.extra) o.extra(bar,s); }
   const svg=view.querySelector('svg'); svg.querySelectorAll('[data-id]').forEach(e=>{ const f=()=>{ if(dead) return; sel=sel===e.dataset.id?null:e.dataset.id; draw(); }; e.onclick=f; e.onkeydown=ev=>{ if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); f(); } }; });
   svg.querySelectorAll('[data-to]').forEach(e=>{ const f=()=>go({t:'slide',id:sel,to:+e.dataset.to}); e.onclick=f; e.onkeydown=ev=>{ if(ev.key==='Enter'||ev.key===' '){ ev.preventDefault(); f(); } }; }); };
  const api={ get s(){ return s; }, set(n){ s=n; sel=null; draw(); }, lock(){ dead=true; sel=null; draw(); }, reset(){ s=start; sel=null; dead=false; draw(); }, draw, go:m=>go(m) };
  function go(m){ if(dead) return; const before=s; if(!G.legal(s).some(x=>x.t===m.t&&(m.t==='collect'||(x.id===m.id&&x.to===m.to)))) return; s=G.apply(s,m); sel=null; draw(); o.move&&o.move(m,before,s,api); }
  draw(); return api; };
 const strat=(a,api,goalText,opts)=>{ /* play against a random opponent; the visitor must keep leaving balanced positions */
  return {}; };
 const rnd=a=>a[Math.floor(Math.random()*a.length)];
 const lbl=(s,id)=>{ const c=s.coins.find(x=>x.id===id); return c.kind==='gold'?'the gold coin':`the penny at space ${c.pos+1}`; };
 /* a "keep it balanced" exercise: the visitor moves, a scripted opponent replies at random, the visitor must keep leaving losing positions */
 const balance=(h,a,cfg)=>{ let busy=false; const T=track(h,Object.assign({},cfg,{ move(m,b,s,t){ if(busy) return; if(s.over){ t.lock(); a.note('<b>You took the gold.</b> '+(cfg.win||'Nothing about that was luck.')); a.ok(); return; }
    if(G.winning(s)){ busy=true; a.note(cfg.mistake||'<b>Not quite.</b> Your opponent could win from here. Press Reset and look for the move that leaves the other player stuck.'); setTimeout(()=>{ busy=false; },50); return; }
    /* balanced: the opponent must move; pick any legal move */
    busy=true; t.lock(); a.note('<b>Balanced.</b> Now your opponent has to move…'); setTimeout(()=>{ const r=rnd(G.legal(s)); const s2=G.apply(s,r); t.reset&&0; t.set(s2); busy=false; if(s2.over){ a.note('The opponent took the gold. Reset and try again.'); return; } a.note(`Your opponent ${r.t==='collect'?'took the leftmost coin':'slid '+lbl(s,r.id)+' to space '+(r.to+1)}. <b>Balance it again.</b>`); if(cfg.after) cfg.after(s2,t); },700); } }));
  return T; };
 const pileView=(host,T,mode)=>{ const box=$('div','ls-pv'); host.appendChild(box); const r=()=>{ const P=G.piles(T.s); const S=P.reduce((x,p)=>x^p.h,0); box.innerHTML=(P.slice().reverse().map(p=>`<div class="ls-pile"><div class="ls-stk">${Array.from({length:p.h},()=>'<i></i>').join('')||'<em>empty</em>'}</div><b>${p.h}</b></div>`).join(''))+(mode==='xor'?`<div class="ls-xor">${P.map(p=>p.h.toString(2).padStart(4,'0')).join(' ⊕ ')||'0'} = <b>${S.toString(2).padStart(4,'0')}</b><br>${S===0?'Zero: the player to move is losing.':'Not zero: the player to move can win.'}</div>`:''); }; return r; };
 const CSSG=`.ls-gt{display:flex;flex-direction:column;gap:8px;align-items:center;width:100%}.ls-gbar{display:flex;gap:8px;align-items:center;justify-content:center;flex-wrap:wrap;min-height:40px}.ls-pv{display:flex;gap:14px;align-items:flex-end;justify-content:center;flex-wrap:wrap;min-height:56px}.ls-stk{display:flex;flex-direction:column-reverse;gap:3px;align-items:center;min-height:14px}.ls-stk i{width:34px;height:9px;border-radius:4px;background:var(--fg)}.ls-stk em{font:500 11px var(--font-mono);color:var(--g5)}.ls-xor{font:600 13px/1.5 var(--font-mono);color:var(--fg);text-align:center;flex-basis:100%;margin-top:4px}`;
 if(!document.getElementById('ls-gcss')){ const st2=$('style'); st2.id='ls-gcss'; st2.textContent=CSSG; document.head.appendChild(st2); }
 return [
 {kind:'goal',title:'Take the gold coin',text:'Coins sit on a row of spaces: pennies and one <b>gold coin</b>. Players take turns. <b>Whoever takes the gold coin wins.</b>',mount(h,a){ A=a; const T=track(h,{n:8,pens:[2,4],gold:6,noTake:true}); T.lock(); a.note('Pennies are worth nothing. Only the gold matters.'); }},
 {kind:'watch',title:'Slide left, or take the leftmost coin',text:'On your turn, either <b>slide one coin to the left</b>, or <b>take the leftmost coin</b> off the board.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[2,4],gold:6,noTake:true}); T.lock(); a.note('Your move.'); return {reset(){ T.reset(); T.lock(); a.note('Your move.'); }, async show(){ T.reset(); await sleep(300); T.go({t:'slide',id:'p2',to:3}); T.lock(); a.note('<b>You slide the second penny left.</b> It can stop on any free space, as long as it moves left.'); await sleep(1500); T.set(G.apply(T.s,{t:'collect'})); T.lock(); a.note('<b>Your opponent takes the leftmost coin</b>, the penny nearest the edge. That uses up their whole turn.'); }}; }},
 {kind:'try',title:'Slide a coin left',text:'Coins sit on a row of spaces. On your turn you may <b>slide one coin to the left</b>, by as many spaces as you like. Select the penny, then a dashed space.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[4],gold:7,noTake:true,move(m,b,s){ { const c0=b.coins.find(c=>c.id===m.id); a.note(`<b>You slid ${c0.kind==='gold'?'the gold coin':'the penny'} from space ${c0.pos+1} to space ${m.to+1}.</b> Coins only ever move left, never right.`); }; a.ok(); T.lock(); }}); a.note('Only spaces to the left are offered.'); return {reset(){ T.reset(); a.note('Only spaces to the left are offered.'); }, async show(){ T.reset(); T.go({t:'slide',id:'p1',to:2}); }}; }},
 {kind:'try',title:'Take the leftmost coin',text:'Instead of sliding, you may <b>take the leftmost coin</b>, wherever it stands. It does not have to reach the first space. Try it.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[3],gold:6,move(m,b,s,t){ if(m.t==='collect'){ a.note('<b>You took the penny.</b> It was three spaces from the edge, and the gold coin did not move. Taking a coin never shifts the others.'); a.ok(); t.lock(); } else a.note('That was a slide. Try the other kind of turn: <b>Take leftmost coin</b>.'); }}); a.note('The penny is the leftmost coin.'); return {reset(){ T.reset(); }, async show(){ T.reset(); T.go({t:'collect'}); }}; }},
 {kind:'cant',title:'Coins can’t jump',text:'A coin <b>cannot land on or jump over</b> another coin. Select the gold coin and look at how far it can go.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[3],gold:6,noTake:true,move(m,b,s){ a.note('<b>You slid the gold coin to space '+(m.to+1)+'.</b> It could not go past the penny at space 4.'); a.ok(); T.lock(); }}); a.note('Select the gold coin. The penny at space 4 stops it.'); return {reset(){ T.reset(); }, async show(){ T.reset(); T.go({t:'slide',id:'gold',to:4}); }}; }},
 {kind:'end',title:'Taking the gold wins',text:'Taking <b>the gold coin wins immediately</b>. Pennies score nothing. Here the gold coin is the leftmost, so you can take it.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[],gold:5,move(m,b,s,t){ if(m.t==='collect'){ a.note('<b>You took the gold.</b> The game is over the moment you do.'); a.ok(); t.lock(); } else a.note('Sliding is allowed, but the gold is leftmost. Take it.'); }}); a.note('The gold coin is the only coin left.'); return {reset(){ T.reset(); }, async show(){ T.reset(); T.go({t:'collect'}); }}; }},
 {kind:'more',title:'A tempting mistake',text:'The gold coin is the second coin. Taking the penny looks like progress, but <b>the gold becomes leftmost, and gold that is leftmost can be taken</b>. See what happens.',mount(h,a){ A=a; const T=track(h,{n:8,pens:[2],gold:5,move(m,b,s,t){ if(m.t==='collect'){ t.lock(); a.note('<b>You took the penny.</b> The gold is now leftmost…'); setTimeout(()=>{ t.set(G.apply(s,{t:'collect'})); t.lock(); a.note('<b>Your opponent took the gold.</b> Making the gold leftmost is not a win. It handed the win to the other player.'); a.ok(); },800); } else { a.note('You slid instead. That is safer, but the tempting move was <b>Take leftmost coin</b>. Reset and try it to see why.'); a.ok(); } }}); a.note('Take the penny.'); return {reset(){ T.reset(); a.note('Take the penny.'); }, async show(){ T.reset(); T.go({t:'collect'}); }}; }},
 {kind:'more',title:'Close the gap',text:'The coins are four spaces apart. <b>Slide the gold coin so it touches the penny.</b> Then, whatever your opponent does, you can close the gap again.',mount(h,a){ A=a; const T=balance(h,a,{n:9,pens:[2],gold:7,pairs:1,mistake:'<b>Not quite.</b> The gap is still open. Press Reset and slide the gold coin right up to the penny.',win:'Closing the gap every time left your opponent with nothing but bad moves.'}); a.note('Look at the space between the two coins.'); return {reset(){ T.reset(); a.note('Look at the space between the two coins.'); }, async show(){ T.reset(); T.go({t:'slide',id:'gold',to:3}); }}; }},
 {kind:'more',title:'Discover: the losing side',text:'The coins already touch, so <b>you are the one who is stuck</b>. Move anything. Then watch how your opponent answers.',mount(h,a){ A=a; const T=track(h,{n:9,pens:[3],gold:4,pairs:1,move(m,b,s,t){ if(s.over){ t.lock(); a.note('You took the gold, but this position cannot come up against a careful opponent.'); a.ok(); return; } t.lock(); a.note('Your opponent answers…'); setTimeout(()=>{ const mv=G.formulaMove(s); if(!mv){ a.note('Your opponent has no winning reply here.'); t.draw(); return; } t.set(G.apply(s,mv)); t.lock(); a.note(`<b>Your opponent closed the gap again.</b> Every move you make opens a gap, and they close it. Eventually the gold is leftmost on your move… for them.`); a.ok(); },800); }}); a.note('Touching coins: the player to move is losing.'); return {reset(){ T.reset(); a.note('Touching coins: the player to move is losing.'); }, async show(){ T.reset(); T.go({t:'slide',id:'p1',to:1}); }}; }},
 {kind:'more',title:'Discover: three coins',text:'With three coins, <b>the last two form a pair</b> and the coin in front is on its own. <b>Slide a coin so the two counted gaps match.</b> The brackets show the gaps that count.',mount(h,a){ A=a; const T=balance(h,a,{n:11,pens:[2,5],gold:10,pairs:2,mistake:'<b>Not quite.</b> The two numbers over the brackets are not equal yet. (The front one counts the spaces up to the coin, and the coin itself.) Press Reset and try again.',win:'Two matching numbers meant whatever your opponent changed, you could change the other to match.'}); a.note('Numbers above the brackets: gap sizes. The dashed one is the front count.'); return {reset(){ T.reset(); }, async show(){ T.reset(); T.go({t:'slide',id:'gold',to:9}); }}; }},
 {kind:'more',title:'Discover: a longer board',text:'On a longer board, <b>pair the coins from the right</b>: last with second last, third last with fourth last, and so on. <b>Gaps between one pair and the next do not count.</b> Slide any coin and watch the numbers.',mount(h,a){ A=a; const T=track(h,{n:13,pens:[1,3,6,9],gold:12,pairs:2,noTake:true,move(m,b,s,t){ a.note('<b>Look at the brackets.</b> Only the gaps inside a pair, and the front count, changed the numbers. Gaps between pairs are ignored.'); a.ok(); }}); a.note('Five coins: two pairs and one coin in front.'); return {reset(){ T.reset(); }, async show(){ T.reset(); T.go({t:'slide',id:'p3',to:5}); }}; }},
 {kind:'more',title:'Discover: hidden Nim piles',text:'Each counted gap behaves like <b>a pile of tokens in Nim</b>. Sliding the right coin of a pair left shrinks that pile. Slide a coin and watch its pile.',mount(h,a){ A=a; const T=track(h,{n:11,pens:[2,5],gold:10,pairs:2,noTake:true,move(m,b,s,t){ redraw(); a.note('<b>The pile changed by the number of spaces you slid.</b> A gap can also grow: sliding the coin on its left would enlarge it. Nim never allows that, and it does not help a player who is behind.'); a.ok(); }}); const box=$('div'); h.appendChild(box); const redraw=pileView(box,T,'piles'); redraw(); a.note('Slide any coin.'); return {reset(){ T.reset(); redraw(); }, async show(){ T.reset(); T.go({t:'slide',id:'gold',to:8}); redraw(); }}; }},
 {kind:'more',title:'Discover: the arithmetic',text:'Piles are balanced when their binary digits <b>cancel out</b>. That test (called XOR, or the Nim-sum) is the mathematics behind the game. <b>You only see it if you press the button.</b>',mount(h,a){ A=a; let shown=false; let redraw; const T=track(h,{n:11,pens:[2,5],gold:10,pairs:2,noTake:true,move(m,b,s,t){ if(redraw) redraw(); }, extra(bar){ const b=$('button','ls-btn'+(shown?'':' ghost'),shown?'Hide the arithmetic':'Show the arithmetic'); b.type='button'; b.onclick=()=>{ shown=!shown; T.draw(); rebuild(); }; bar.appendChild(b); }}); const box=$('div'); h.appendChild(box); const rebuild=()=>{ box.innerHTML=''; if(shown){ redraw=pileView(box,T,'xor'); redraw(); } else redraw=null; }; a.note('Optional. The strategy works without it.'); return {reset(){ T.reset(); shown=false; T.draw(); rebuild(); }}; }}
 ]; }

const TABLE={ '4x4-tic-tac-toe':ttt4,'recursive-tic-tac-toe':ult,'3d-tic-tac-toe':cube,'nim':nim,'chomp':chomp,'quarto':quarto,'sim':sim,'pentago':pentago,'toot-otto':toot,'domineering':domineering,'notakto':notakto,'crowded-room':crowd,'last-message':message,'gold-coin':gold };
const EXTRA={};
window.ZLessons={ add(slug,fn){ EXTRA[slug]=fn; }, get(slug){ try{ if(EXTRA[slug]) return EXTRA[slug](); return TABLE[slug]?TABLE[slug]():null; }catch(e){ console.error(e); return null; } }, has:slug=>!!(TABLE[slug]||EXTRA[slug]) };
})();
